SELECT id, title, content, summary, publisher, publisher_type, publisher_dept,
       top_flag, status, create_time, update_time
FROM admin_notice

    AND title LIKE CONCAT('%', #{title}, '%')

        AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))

    AND status = #{status}
    AND publisher_type = #{publisherType}
    AND publisher_dept = #{publisherDept}
    AND create_time >= #{startTime}
    AND create_time < #{endTime}

ORDER BY top_flag DESC, create_time DESC
LIMIT #{offset}, #{size}

